mapper.select:
SELECT ctn.notice_status AS tabFlag, count(1) AS count FROM cfg_third_notice as ctn WHERE ctn.is_deleted=FALSE
${params.permissionSql}
GROUP BY ctn.notice_status

mapper.sql:
SELECT ctn.id as id, ctn.create_user_id as createUserId, ctn.create_user_name as createUserName, ctn.create_time as createTime, ctn.update_user_id as updateUserId, ctn.update_user_name as updateUserName, ctn.update_time as updateTime, ctn.version as version, ctn.is_deleted as isDeleted, ctn.business_type as businessType, ctn.notice_node as noticeNode, ctn.method as method, ctn.notice_status as noticeStatus, ctn.title as title, ctn.notice_type as noticeType, ctn.url as url, ctn.cron as cron, ctn.role_type as roleType, ctn.specific_person as specificPerson, ctn.notice_method as noticeMethod, ctn.post as post FROM cfg_third_notice AS ctn WHERE ${params.sqlMap.default} AND ctn.is_deleted = FALSE
and ctn.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ctn.create_time DESC
